@using Umbraco.Cms.Web.Common.PublishedModels
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@{
    Layout = "Layout.cshtml";
}
<main class="max-w-6xl mx-auto px-4 py-12">
    <h1 class="text-4xl font-bold mb-8">@Model.Name</h1>
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    <section class="mt-16">
        <h2 class="text-2xl font-semibold mb-6">Latest Posts</h2>
        @{
            var posts = Model.Children<BlogPost>();
        }
        @if (posts?.Any() == true)
        {
            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">
                @foreach (var post in posts)
                {
                    <article class="bg-white rounded-lg shadow-md overflow-hidden">
                        <div class="p-6">
                            <h3 class="text-xl font-bold mb-2">
                                <a href="@post.Url()" class="text-blue-600 hover:text-blue-800">@post.Name</a>
                            </h3>
                            @if (post.HasValue("excerpt"))
                            {
                                <p class="text-gray-600">@post.Value("excerpt")</p>
                            }
                            <a href="@post.Url()" class="mt-4 inline-block text-blue-600 hover:text-blue-800 font-medium">Read more →</a>
                        </div>
                    </article>
                }
            </div>
        }
        else
        {
            <p class="text-gray-500">No posts yet.</p>
        }
    </section>
</main>

